    let ledMake = makePrefix(ledType?.Make?.value);

      const tacValidityLed = ledType?.TAC_Validity?.value || "";
      const tacNumberLed = ledType?.TAC_Number?.value || "";
      const copCertLed = ledType?.CoP_Cert_No_with_validity_date?.value || "";
